/** Shared humanoid hitboxes for offline bots AND server-authoritative players.
 * Body parts match the silhouettes generated by FPSEngine.addCombatantMesh.
 * Arms include aiming/IK reach margins and legs extend all the way to the boots.
 */
import { rayBox, type Vec3 } from "./game-protocol";
type Hit = {t:number;head:boolean};
export function rayCombatantHit(origin:Vec3, dir:Vec3, feet:Vec3):Hit|null {
  const volume:(readonly [number,number,number,number,number,number,boolean])[]=[
    [0,1.62,0,.19,.18,.19,true],      // head, including visor
    [0,1.17,0,.28,.32,.20,false],      // torso and shoulders
    [0,.85,0,.245,.17,.19,false],      // hips
    [-.39,1.08,0,.20,.39,.27,false],   // articulated left arm/hand reach
    [.39,1.08,0,.20,.39,.27,false],    // right arm/hand reach
    [-.13,.42,.03,.125,.44,.20,false], // upper/lower leg and boot
    [.13,.42,.03,.125,.44,.20,false],
  ];
  let nearest:Hit|null=null;
  for(const [dx,dy,dz,hx,hy,hz,head] of volume){
    const t=rayBox(origin,dir,[feet[0]+dx,feet[1]+dy,feet[2]+dz],[hx,hy,hz]);
    if(t!==null&&t>=0&&(!nearest||t<nearest.t-.00001||(head&&Math.abs(t-nearest.t)<.00001)))
      nearest={t,head};
  }
  return nearest;
}
